package dev.bennett.codexmeter;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import androidx.appcompat.app.*;import androidx.core.os.LocaleListCompat;
/** First setup, locale/rotation draft, dialog lifecycle; explicitly synthetic owner only. */
public final class Beta995LifecycleNativeTest extends Instrumentation {
    volatile Activity resumed;int checks;Throwable failure;
    void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    void main(Runnable run){runOnMainSync(()->{try{run.run();}catch(Throwable t){failure=t;}});if(failure!=null)throw new AssertionError(failure);}
    void idle(long millis)throws Exception{Thread.sleep(millis);waitForIdleSync();}
    final Application.ActivityLifecycleCallbacks events=new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){resumed=a;}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();Application app=(Application)getTargetContext().getApplicationContext();app.registerActivityLifecycleCallbacks(events);Context c=getTargetContext();String language=AppCompatDelegate.getApplicationLocales().toLanguageTags();String originalName=BetaIdentity.prefs(c).getString("name","");boolean originalDone=BetaIdentity.done(c);try{
        check(c.getPackageName().equals("dev.bennett.codexmeter.trial")&&Build.MODEL.contains("sdk")&&TrialDemo.active(c),"Synthetic owner only");String account=SubscriptionStore.accountKey(c);long total=BetaGrowthStore.load(c,account).getLong("total");
        BetaIdentity.prefs(c).edit().putBoolean("setup_done",false).remove("name").commit();BetaSetupActivity setup=(BetaSetupActivity)startActivitySync(new Intent(c,BetaSetupActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));idle(400);String draft="작성 중 Draft 이름";main(()->setup.name.setText(draft));
        main(()->AppCompatDelegate.setApplicationLocales(LocaleListCompat.forLanguageTags("en")));idle(1600);check(resumed instanceof BetaSetupActivity,"Setup recreated in English");BetaSetupActivity english=(BetaSetupActivity)resumed;main(()->{check(english.name.getText().toString().equals(draft),"Draft survives language change");check(!BetaCopy.ko(english),"Actual English resources");english.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);});idle(1100);check(resumed instanceof BetaSetupActivity,"Setup rotation restored");BetaSetupActivity landscape=(BetaSetupActivity)resumed;main(()->{check(landscape.name.getText().toString().equals(draft),"Draft survives rotation");landscape.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);});idle(1000);BetaSetupActivity portrait=(BetaSetupActivity)resumed;main(()->portrait.finishSetup(draft));idle(600);check(BetaIdentity.name(c).equals(draft)&&BetaIdentity.done(c),"Setup saves independent name marker");
        TrialWelcomeActivity welcome=(TrialWelcomeActivity)startActivitySync(new Intent(c,TrialWelcomeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));idle(400);check(resumed instanceof TrialWelcomeActivity,"Ordinary update does not ask name again");main(welcome::finish);
        BetaCatalogActivity titles=(BetaCatalogActivity)startActivitySync(new Intent(c,BetaCatalogActivity.class).putExtra("titles",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));idle(500);main(()->BetaIdentity.edit(titles,()->{}));idle(400);main(()->{BetaNameDialog dialog=(BetaNameDialog)titles.getSupportFragmentManager().findFragmentByTag("beta-name-editor");check(dialog!=null&&dialog.getDialog().isShowing(),"Fragment name editor opens");dialog.input.setText("유지되는 이름 Kept");});main(()->AppCompatDelegate.setApplicationLocales(LocaleListCompat.forLanguageTags("ko")));idle(1300);
        check(resumed instanceof BetaCatalogActivity,"Title screen recreated in Korean");BetaCatalogActivity korean=(BetaCatalogActivity)resumed;main(()->{BetaNameDialog editor=(BetaNameDialog)korean.getSupportFragmentManager().findFragmentByTag("beta-name-editor");check(editor!=null&&editor.input.getText().toString().equals("유지되는 이름 Kept"),"Editor draft survives locale change");editor.dismiss();});idle(350);main(()->{check(korean.getSupportFragmentManager().findFragmentByTag("beta-name-editor")==null,"Dialog fragment/touch dim layer removed");korean.finish();});
        check(BetaGrowthStore.load(c,account).getLong("total")==total,"Setup/name/locale/rotation do not grant XP");
        result.putString("stream","Beta 9.9.5 lifecycle: "+checks+" checks passed; setup/locale/rotation/dialog/name persistence; synthetic only.\n");finish(-1,result);
    }catch(Throwable error){result.putString("stream",android.util.Log.getStackTraceString(error));finish(0,result);}finally{app.unregisterActivityLifecycleCallbacks(events);BetaIdentity.prefs(c).edit().putString("name",originalName).putBoolean("setup_done",originalDone).remove("draft_name").commit();runOnMainSync(()->{if(resumed!=null&&!resumed.isFinishing())resumed.finish();AppCompatDelegate.setApplicationLocales(LocaleListCompat.forLanguageTags(language));});}}
}
